!!!!!!!! D01.!!!!!!!!!!
!!!!!!!! 1. Roof !!!!!!!!!!!!!!
      IF (ldaps_ws1(kk) < inflow_ws_01(kk)) THEN

      if (roof_1 < 0.97) then
      u11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*uu111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*uu112(i,j)
      v11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*vv111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*vv112(i,j)
      w11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*ww111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*ww112(i,j)
      dtemp11(i,j) =  (wd1_a*dt111(i,j) + wd1_b*dt112(i,j))
      rtemp11(i,j) =  (wd1_a*rt111(i,j) + wd1_b*rt112(i,j))

      else if (roof_1 > 1.07) then
      u11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*uu111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*uu112(i,j)
      v11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*vv111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*vv112(i,j)
      w11(i,j)= wd1_a*ldaps_ws1(kk)/inflow_ws_01(kk)*ww111(i,j) + wd1_b*ldaps_ws1(kk)/inflow_ws_01(kk)*ww112(i,j)
      dtemp11(i,j) =  (wd1_a*dt111(i,j) + wd1_b*dt112(i,j))
      rtemp11(i,j) =  (wd1_a*rt111(i,j) + wd1_b*rt112(i,j))

      else if (roof_1 >= 0.97 .and. roof_1 <= 1.07) THEN
      u11(i,j)=  wd1_a*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*uu111(i,j) + wd1_a*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*uu115(i,j) + wd1_b*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*uu112(i,j) + wd1_b*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*uu116(i,j)
      v11(i,j)=  wd1_a*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*vv111(i,j) + wd1_a*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*vv115(i,j) + wd1_b*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*vv112(i,j) + wd1_b*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*vv116(i,j)
      w11(i,j)=  wd1_a*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*ww111(i,j) + wd1_a*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*ww115(i,j) + wd1_b*(roof_temp1_b/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*ww112(i,j) + wd1_b*(roof_temp1_a/0.025)*ldaps_ws1(kk)/inflow_ws_01(kk)*ww116(i,j)
      dtemp11(i,j)=  wd1_a*(roof_temp1_b/0.025)*dt111(i,j) + wd1_a*(roof_temp1_a/0.025)*dt115(i,j) + wd1_b*(roof_temp1_b/0.025)*dt112(i,j) + wd1_b*(roof_temp1_a/0.025)*dt116(i,j)
      rtemp11(i,j)=  wd1_a*(roof_temp1_b/0.025)*rt111(i,j) + wd1_a*(roof_temp1_a/0.025)*rt115(i,j) + wd1_b*(roof_temp1_b/0.025)*rt112(i,j) + wd1_b*(roof_temp1_a/0.025)*rt116(i,j)
      end if

      ENDIF

      IF (ldaps_ws1(kk) > inflow_ws_08(kk)) THEN

