      rtemp102(i,j)=  wd10_a*(wall_temp10_b/0.02)*rt1021(i,j) + wd10_a*(wall_temp10_a/0.02)*rt1025(i,j) + wd10_b*(wall_temp10_b/0.02)*rt1022(i,j) + wd10_b*(wall_temp10_a/0.02)*rt1026(i,j)
