      w166(i,j)= wd16_a*(ws16_b/(ws16_a+ws16_b))*ww1661(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*ww1663(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*ww1662(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*ww1664(i,j)
      dtemp166(i,j)=  wd16_a*(ws16_b/(ws16_a+ws16_b))*dt1661(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*dt1663(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*dt1662(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*dt1664(i,j)
      rtemp166(i,j)=  wd16_a*(ws16_b/(ws16_a+ws16_b))*rt1661(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*rt1663(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*rt1662(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*rt1664(i,j)

      else IF (water_16 >= 0.95 .and. water_16 <= 1.11) THEN
      u166(i,j)= wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*uu1661(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*uu1662(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*uu1663(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*uu1664(i,j) + wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*uu1665(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*uu1666(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*uu1667(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*uu1668(i,j)
      v166(i,j)= wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*vv1661(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*vv1662(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*vv1663(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*vv1664(i,j) + wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*vv1665(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*vv1666(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*vv1667(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*vv1668(i,j)
      w166(i,j)= wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*ww1661(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*ww1662(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*ww1663(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*ww1664(i,j) + wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*ww1665(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*ww1666(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*ww1667(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*ww1668(i,j)
