      rtemp166(i,j)= wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*rt1661(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_b/0.04)*rt1662(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*rt1663(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_b/0.04)*rt1664(i,j) + wd16_a*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*rt1665(i,j) + wd16_b*(ws16_b/(ws16_a+ws16_b))*(water_temp16_a/0.04)*rt1666(i,j) + wd16_a*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*rt1667(i,j) + wd16_b*(ws16_a/(ws16_a+ws16_b))*(water_temp16_a/0.04)*rt1668(i,j)
      end if
      ENDIF
      !S2_end ---------------------------------------!


!!!!!!!! Integral D01 ~ D16 (Superposition) !!!!!!!!!

      uu1(i,j) = (u11(i,j) + u12(i,j) + u13(i,j) + u14(i,j) + u15(i,j) + u16(i,j))/6.
      vv1(i,j) = (v11(i,j) + v12(i,j) + v13(i,j) + v14(i,j) + v15(i,j) + v16(i,j))/6.
      ww1(i,j) = (w11(i,j) + w12(i,j) + w13(i,j) + w14(i,j) + w15(i,j) + w16(i,j))/6.
      ftemp1(i,j) = ((ldaps_t1(kk)) * (rtemp11(i,j) + rtemp12(i,j) + rtemp13(i,j) + rtemp14(i,j) + rtemp15(i,j) + rtemp16(i,j) - 5. )) ! Unit : K

      uu2(i,j) = (u21(i,j) + u22(i,j) + u23(i,j) + u24(i,j) + u25(i,j) + u26(i,j))/6.
      vv2(i,j) = (v21(i,j) + v22(i,j) + v23(i,j) + v24(i,j) + v25(i,j) + v26(i,j))/6.
      ww2(i,j) = (w21(i,j) + w22(i,j) + w23(i,j) + w24(i,j) + w25(i,j) + w26(i,j))/6.
